    /** Sustituye todos los conjuros de catálogo (esPropio = false) por la lista actual. */
    suspend fun seedCatalog(repo: Repository) {
        repo.deleteNonOwnConjuros()
        val conjuros = allMageSpells.map { spell ->
            Conjuro(
                nombre = spell.nombre,
                nivel = spell.nivel,
                tl = spell.tl,
                componentes = spell.componentes,
                alcance = spell.alcance,
                duracion = spell.duracion,
                ts = spell.ts,
                rc = spell.rc,
                descripcion = spell.descripcion,
                esPropio = false
            )
        }
        repo.insertConjuros(conjuros)
    }
}
